 gym:[['벤치프레스','가슴'],['인클라인 벤치프레스','가슴'],['덤벨 프레스','가슴'],['체스트 프레스','가슴'],['케이블 플라이','가슴'],['푸시업','가슴'],['바벨 컬','팔'],['덤벨 컬','팔'],['해머 컬','팔'],['케이블 컬','팔'],['트라이셉스 푸시다운','팔'],['스컬 크러셔','팔'],['딥스','팔'],['숄더 프레스','어깨'],['덤벨 숄더 프레스','어깨'],['사이드 레터럴 레이즈','어깨'],['프론트 레이즈','어깨'],['리어 델트 플라이','어깨'],['페이스 풀','어깨'],['풀업','등'],['랫풀다운','등'],['바벨 로우','등'],['시티드 케이블 로우','등'],['원암 덤벨 로우','등'],['데드리프트','등'],['스쿼트','하체'],['레그 프레스','하체'],['레그 익스텐션','하체'],['레그 컬','하체'],['런지','하체'],['루마니안 데드리프트','하체'],['카프 레이즈','하체']].map(([name,group])=>({id:'gym_'+name,name,group})),
